/**
 * Client entry point for blog content. `virtual:blog` is generated by
 * build/blog-plugin.js; in production it only contains published posts.
 *
 * `previewMode` is true on the dev server, where drafts and future-dated posts
 * are included (with `state` "draft" or "scheduled") so they can be previewed.
 */
import { posts, loadPost, previewMode } from "virtual:blog";

export { posts, loadPost, previewMode };

/** Mirrors the production filter, for places that must never link to drafts. */
export const isLive = (post) => post.state === "published";

export const livePosts = posts.filter(isLive);
